import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";
import { MAPA_V3 } from "./mapaV3";
import {
  Cap, Check, Cross, IcoAbcd, IcoBag, IcoBoleto, IcoCalendar, IcoCalendarMini, IcoCard, IcoClip, IcoConcurso, IcoFolder,
  IcoHeadset, IcoLines, IcoMedal, IcoPaid, IcoPencil, IcoPix, IcoUni, Material, Row,
} from "./LorranyEja";

// DELTA CIDADE JARDIM (Lorrany EJA) · v2. Retorno sobre a v1: "zoom desnecessário vindo para cima, perde o
// alinhamento; tire as pausas da narração; olhe o último vídeo feito para essa empresa" (Lorran-EJA-150mes-motion-v2).
// Agora no jeito daquele vídeo (src/Lorran/LorranEja7Ref.tsx): frase no alto palavra por palavra com a chave grifada,
// desenho no meio, tudo num bloco centrado; fundo liso que troca de cor a cada batida; logo fixo num selo embaixo.
// Sem câmera andando: só um soco curto de escala (0,35 s, centrado) na troca de fundo; o que entra fica parado.
// Voz: src/voz-v2.wav (voz-v1-r1 sem as pausas, 121,5 s). Tempos = edit/transcripts/voz-v2.json.

const { fontFamily: F } = loadMontserrat("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FI } = loadMontserrat("italic", { weights: ["800", "900"], subsets: ["latin", "latin-ext"] });

export const LY2_FPS = 30;
export const LY2_DUR = 123.1;
export const LY2_FRAMES = Math.round(LY2_DUR * LY2_FPS);

const GREEN = "#0A6842";
const DEEP = "#053D27";
const LEAF = "#5BAA3C";
const LIME = "#B9E27E";
const INK = "#13261C";
const CREAM = "#F3F5EC";
const WHITE = "#FFFFFF";
const RED = "#E0402F";
const ORANGE = "#F29A1F";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const sp = (t: number, a: number, damping = 13, stiffness = 200) =>
  spring({ frame: Math.round((t - a) * LY2_FPS), fps: LY2_FPS, config: { damping, stiffness } });
const img = (f: string) => staticFile(`lorrany-eja/${f}`);

type Bg = "cream" | "green" | "deep" | "lime";
const BG: Record<Bg, string> = { cream: CREAM, green: GREEN, deep: DEEP, lime: LIME };
const ink = (b: Bg) => (b === "cream" || b === "lime" ? INK : WHITE);

// legenda no alto: palavra por palavra, chave grifada; palavra ainda não dita não ocupa espaço
type Wd = [string, number, boolean?];
const Caption: React.FC<{ t: number; bg: Bg; lines: Wd[][]; size?: number }> = ({ t, bg, lines, size = 66 }) => (
  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
    {lines.map((ln, i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.22, height: size * 1.22, color: ink(bg), textAlign: "center", whiteSpace: "nowrap" }}>
        {ln.map(([w, at, hi], j) => {
          if (t < at - 0.01) return null;
          const q = k(t, at, 0.18);
          const h = hi ? k(t, at + 0.12, 0.3) : 0;
          return (
            <span key={j} style={{ position: "relative", display: "inline-block", margin: "0 0.12em", opacity: q, transform: `translateY(${(1 - q) * 18}px)` }}>
              {hi && <span style={{ position: "absolute", left: "-0.12em", right: "-0.12em", top: "0.12em", bottom: "0.02em", background: bg === "lime" ? WHITE : LIME, transform: `scaleX(${h})`, transformOrigin: "0 50%", zIndex: 0 }} />}
              <span style={{ position: "relative", zIndex: 1, color: hi && h > 0.3 ? INK : undefined }}>{w}</span>
            </span>
          );
        })}
      </div>
    ))}
  </div>
);
// atalho: frase "a b c" com tempos a partir de uma lista
const L = (words: string, times: number[], hi: number[] = []): Wd[] => words.split(" ").map((w, i) => [w, times[i], hi.includes(i)]);

// cena: fundo liso, soco curto de escala na entrada (centrado), sem câmera andando
const Beat: React.FC<{ t: number; a: number; b: number; bg: Bg; wipe?: boolean; children: React.ReactNode }> = ({ t, a, b, bg, wipe, children }) => {
  if (t < a || t >= b) return null;
  const punch = 1.04 - 0.04 * k(t, a, 0.35);
  const clip = wipe ? `circle(${k(t, a, 0.45) * 130}% at 50% 55%)` : "none";
  return (
    <AbsoluteFill style={{ background: BG[bg], clipPath: clip }}>
      <AbsoluteFill style={{ transform: `scale(${punch.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
const Stack: React.FC<{ gap?: number; children: React.ReactNode }> = ({ gap = 60, children }) => (
  <div style={{ position: "absolute", left: 100, right: 100, top: 70, height: 1570, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap }}>{children}</div>
);
const Box: React.FC<{ w: number; h: number; x: number; y: number; zoom?: number; children: React.ReactNode }> = ({ w, h, x, y, zoom = 1, children }) => (
  <div style={{ position: "relative", width: w * zoom, height: h * zoom, flex: "none" }}>
    <div style={{ position: "absolute", left: -x * zoom, top: -y * zoom, width: 1080, height: 1920, transform: `scale(${zoom})`, transformOrigin: "0 0" }}>{children}</div>
  </div>
);
const Pop: React.FC<{ t: number; at: number; children: React.ReactNode; from?: number; rot?: number; dx?: number }> = ({ t, at, children, from = 0.4, rot = 0, dx = 0 }) => {
  if (t < at - 0.02) return null;
  const s = sp(t, at, 12, 230);
  return <div style={{ transform: `translateX(${(1 - s) * dx}px) scale(${from + (1 - from) * s}) rotate(${(1 - s) * rot}deg)`, opacity: Math.min(1, s * 3) }}>{children}</div>;
};
// reserva o lugar do que ainda vai entrar, para o bloco não pular quando entra
const Slot: React.FC<{ w?: number; h: number; t: number; at: number; children: React.ReactNode }> = ({ w, h, t, at, children }) => (
  <div style={{ width: w, height: h, flex: "none", display: "flex", alignItems: "center", justifyContent: "center" }}>{t > at - 0.03 ? children : null}</div>
);
const Badge: React.FC = () => (
  <div style={{ position: "absolute", left: 0, right: 0, top: 1690, display: "flex", justifyContent: "center" }}>
    <div style={{ padding: "22px 40px", borderRadius: 28, background: WHITE, boxShadow: "0 14px 40px rgba(0,0,0,0.18)" }}>
      <Img src={img("logo-verde.png")} style={{ width: 420, display: "block" }} />
    </div>
  </div>
);
const Photo: React.FC<{ t: number; at: number; src: string; w: number; ratio: number; border?: number }> = ({ t, at, src, w, ratio, border = 10 }) => {
  const s = sp(t, at, 16, 140);
  return (
    <div style={{ width: w, height: w / ratio, flex: "none", opacity: t < at - 0.02 ? 0 : Math.min(1, s * 2.5), transform: `translateY(${(1 - s) * 160}px) scale(${(0.92 + 0.08 * s).toFixed(4)}) rotate(${(1 - s) * -3}deg)` }}>
      <div style={{ width: "100%", height: "100%", borderRadius: 36, overflow: "hidden", border: `${border}px solid ${WHITE}`, background: WHITE, boxShadow: "0 30px 80px rgba(0,0,0,0.25)", boxSizing: "border-box" }}>
        <Img src={img(src)} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
      </div>
    </div>
  );
};
const pill = (txt: React.ReactNode, bg: string, fg: string, size = 64) => (
  <div style={{ display: "flex", alignItems: "center", gap: 20, padding: "14px 44px 18px", borderRadius: 26, background: bg, fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: size, color: fg, whiteSpace: "nowrap", boxShadow: "0 20px 50px rgba(0,0,0,0.22)" }}>{txt}</div>
);
// capítulo: número numa bola + 5 pontos de progresso
const ChapterMark: React.FC<{ t: number; at: number; n: number; bg: Bg }> = ({ t, at, n, bg }) => (
  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 50 }}>
    <Pop t={t} at={at} from={0.2} rot={-120}>
      <div style={{ width: 340, height: 340, borderRadius: 170, background: bg === "lime" ? GREEN : LIME, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 30px 80px rgba(0,0,0,0.3)" }}>
        <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 240, color: bg === "lime" ? WHITE : GREEN, marginLeft: -14, lineHeight: 1 }}>{n}</span>
      </div>
    </Pop>
    <div style={{ display: "flex", gap: 22 }}>
      {[1, 2, 3, 4, 5].map((i) => {
        const q = i === n ? k(t, at + 0.3, 0.4) : 1;
        const on = bg === "cream" || bg === "lime" ? GREEN : LIME;
        const off = bg === "cream" || bg === "lime" ? "rgba(10,104,66,0.2)" : "rgba(255,255,255,0.22)";
        return <div key={i} style={{ width: i === n ? 30 + 60 * q : 30, height: 30, borderRadius: 15, background: i <= n ? on : off, opacity: i < n ? 0.6 : 1 }} />;
      })}
    </div>
  </div>
);

// folha de caderno com os documentos (arte da cliente)
const DOCS: [string, number][] = [
  ["RG", 55.6], ["CPF", 55.95], ["Título de eleitor", 56.3], ["Comprovante de residência", 56.7],
  ["Certidão de nascimento ou casamento", 57.1], ["Foto 3x4", 57.5], ["Certificado do Ensino Fundamental", 58.12],
];
const Docs: React.FC<{ t: number; at: number; hi: number }> = ({ t, at, hi }) => {
  const s = sp(t, at, 15, 160);
  return (
    <div style={{ position: "relative", width: 840, height: 1150, flex: "none", borderRadius: 30, background: "#FBFBF7", boxShadow: "0 36px 90px rgba(0,0,0,0.35)", transform: `translateY(${(1 - s) * 700}px) rotate(${(1 - s) * -6}deg)`, opacity: Math.min(1, s * 2), padding: "28px 46px 0 110px", boxSizing: "border-box" }}>
      {Array.from({ length: 13 }).map((_, i) => <div key={i} style={{ position: "absolute", left: 30, top: 46 + i * 84, width: 30, height: 30, borderRadius: 15, background: INK }} />)}
      {DOCS.map(([txt, a], i) => {
        const q = k(t, a, 0.3);
        const h = i === 6 ? k(t, hi, 0.35) : 0;
        return (
          <div key={i} style={{ position: "relative", display: "flex", alignItems: "center", gap: 26, height: 156, borderBottom: "3px solid #DDE3DD", opacity: q, transform: `translateX(${(1 - q) * 60}px)` }}>
            <div style={{ position: "absolute", left: -20, right: -24, top: 14, bottom: 14, borderRadius: 22, background: LIME, opacity: 0.55 * h }} />
            <div style={{ position: "relative" }}><Check t={t} at={a + 0.1} size={70} /></div>
            <div style={{ position: "relative", fontFamily: F, fontWeight: 700, fontSize: txt.length > 20 ? 42 : 52, lineHeight: 1.1, color: GREEN, whiteSpace: txt.length > 26 ? "normal" : "nowrap", width: 580 }}>{txt}</div>
          </div>
        );
      })}
    </div>
  );
};

// planos de pagamento (arte da cliente)
const PLANS: { name: string; x?: string; price: string; note: string; at: number }[] = [
  { name: "FLASH", price: "R$ 1.050", note: "à vista", at: 70.9 },
  { name: "VIP", x: "2x", price: "R$ 525", note: "mensais", at: 71.65 },
  { name: "FLEX", x: "3x", price: "R$ 350", note: "mensais", at: 72.4 },
  { name: "LIGHT", x: "5x", price: "R$ 210", note: "mensais", at: 73.15 },
  { name: "ZEN", x: "7x", price: "R$ 150", note: "mensais", at: 73.9 },
];
const PlanCard: React.FC<{ t: number; i: number }> = ({ t, i }) => {
  const p = PLANS[i];
  if (t < p.at - 0.02) return <div style={{ width: 860, height: 170, flex: "none" }} />;
  const s = sp(t, p.at, 13, 210);
  const dir = i % 2 ? 1 : -1;
  return (
    <div style={{ width: 860, height: 170, flex: "none", boxSizing: "border-box", borderRadius: 32, background: WHITE, border: `5px solid ${GREEN}`, display: "flex", alignItems: "center", padding: "0 34px", gap: 24, boxShadow: "0 20px 46px rgba(0,0,0,0.25)",
      opacity: Math.min(1, s * 3), transform: `translateX(${(1 - s) * 360 * dir}px) rotate(${(1 - s) * 4 * dir}deg)` }}>
      <div style={{ width: 300, flex: "none", padding: "16px 0", borderRadius: 60, background: `linear-gradient(90deg, ${GREEN}, #12B23A)`, textAlign: "center", fontFamily: F, fontWeight: 800, fontSize: 40, color: WHITE }}>EJA · {p.name}</div>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 12, whiteSpace: "nowrap" }}>
          {p.x && <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 62, color: GREEN }}>{p.x}</span>}
          <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 72, color: RED, letterSpacing: "-0.02em" }}>{p.price}</span>
        </div>
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: 30, color: GREEN, marginTop: -4 }}>{p.note}</div>
      </div>
    </div>
  );
};

const fmt = (n: number) => n.toLocaleString("pt-BR");

// v3 (retorno da cliente: voz monótona e lenta): voz nova mais expressiva e 1,2x mais rápida (voz-v3-rapida.wav).
// As cenas continuam escritas nos tempos da v2; o tempo do vídeo é convertido de volta para a v2 palavra por palavra.
export const LY3_DUR = 98.3;
export const LY3_FRAMES = Math.round(LY3_DUR * LY2_FPS);
const paraV2 = (x: number) => {
  let i = 0;
  while (i < MAPA_V3.length - 2 && MAPA_V3[i + 1][1] <= x) i++;
  const [a0, b0] = MAPA_V3[i], [a1, b1] = MAPA_V3[i + 1];
  return a0 + ((x - b0) * (a1 - a0)) / (b1 - b0);
};

export const LorranyEjaV2: React.FC<{ audio?: boolean; v3?: boolean }> = ({ audio = true, v3 = false }) => {
  const frame = useCurrentFrame();
  const t = v3 ? paraV2(frame / LY2_FPS) : frame / LY2_FPS;
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {audio && <Audio src={img(v3 ? "mix-v3.wav" : "mix-v2.wav")} />}

      {/* 1 · abertura */}
      <Beat t={t} a={-0.2} b={2.2} bg="cream">
        <Stack gap={70}>
          <Pop t={t} at={0.05} from={0.3} rot={-20}><Cap t={t} at={0.05} size={340} /></Pop>
          <Caption t={t} bg="cream" size={80} lines={[L("Vou te explicar", [0.15, 0.37, 0.47]), L("como funciona", [1.23, 1.53], [0, 1])]} />
        </Stack>
      </Beat>
      <Beat t={t} a={2.2} b={4.95} bg="deep">
        <Stack>
          <Caption t={t} bg="deep" size={72} lines={[L("todo o processo", [2.23, 2.43, 2.51]), L("para concluir o", [3.13, 3.37, 3.91]), L("Ensino Médio", [3.99, 4.37], [0, 1])]} />
          <Pop t={t} at={2.3} from={0.6}>
            <div style={{ width: 860, padding: "52px 56px", borderRadius: 40, background: "#0C5A3A", boxSizing: "border-box" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontFamily: F, fontWeight: 800, fontSize: 60, color: WHITE }}>
                <span>Ensino Médio</span>
                <span style={{ display: "flex", alignItems: "center", gap: 16, color: LIME, fontVariantNumeric: "tabular-nums" }}>{Math.round(100 * k(t, 2.5, 1.8))}%{t > 4.2 && <Check t={t} at={4.25} size={64} bg={LEAF} />}</span>
              </div>
              <div style={{ marginTop: 30, height: 44, borderRadius: 22, background: "rgba(255,255,255,0.15)", overflow: "hidden" }}>
                <div style={{ width: `${100 * k(t, 2.5, 1.8)}%`, height: "100%", borderRadius: 22, background: `linear-gradient(90deg, ${LEAF}, ${LIME})` }} />
              </div>
            </div>
          </Pop>
        </Stack>
      </Beat>
      <Beat t={t} a={4.95} b={6.9} bg="lime" wipe>
        <Stack gap={50}>
          <Caption t={t} bg="lime" size={68} lines={[L("aqui na", [5.09, 5.37]), L("Delta Cidade Jardim", [5.55, 5.89, 6.29], [0, 1, 2])]} />
          <Photo t={t} at={5.05} src="f-delta3.jpg" w={600} ratio={1105 / 1600} />
        </Stack>
      </Beat>

      {/* 2 · capítulo 1: modalidade */}
      <Beat t={t} a={6.9} b={10.05} bg="green">
        <Stack gap={80}>
          <ChapterMark t={t} at={6.97} n={1} bg="green" />
          <Caption t={t} bg="green" size={70} lines={[L("Primeiro, vamos", [6.97, 7.67]), L("entender a", [7.93, 8.42]), L("modalidade de ensino", [8.52, 9.28, 9.42], [0, 1, 2])]} />
        </Stack>
      </Beat>

      {/* 3 · EJA */}
      <Beat t={t} a={10.05} b={14.85} bg="cream">
        <Stack gap={50}>
          <Caption t={t} bg="cream" size={68} lines={[L("Trabalhamos com a", [10.1, 10.72, 10.88])]} />
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
            {([["E", "ducação de", 10.96], ["J", "ovens e", 11.74], ["A", "dultos", 12.32]] as [string, string, number][]).map(([l, rest, at], i) => {
              const s = sp(t, at, 13, 200);
              const fold = k(t, 14.34, 0.4);
              return (
                <div key={i} style={{ height: 170, display: "flex", alignItems: "baseline", opacity: t < at - 0.02 ? 0 : Math.min(1, s * 3) * (1 - 0.6 * fold), transform: `translateX(${(1 - s) * -200}px)` }}>
                  <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 160, lineHeight: 1, color: GREEN }}>{l}</span>
                  <span style={{ fontFamily: F, fontWeight: 700, fontSize: 82, color: INK }}>{rest}</span>
                </div>
              );
            })}
          </div>
          <Caption t={t} bg="cream" size={64} lines={[L("conhecida como", [13.18, 13.88])]} />
          <Slot h={260} t={t} at={14.34}>
            <Pop t={t} at={14.34} from={0.3} rot={12}>
              <div style={{ padding: "4px 70px 16px", borderRadius: 60, background: GREEN, boxShadow: "0 30px 70px rgba(3,40,24,0.3)" }}>
                <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 220, lineHeight: 1, color: LIME }}>EJA</span>
              </div>
            </Pop>
          </Slot>
        </Stack>
      </Beat>

      {/* 4 · 18 anos ou mais */}
      <Beat t={t} a={14.85} b={20.4} bg="deep" wipe>
        <Stack gap={56}>
          <Caption t={t} bg="deep" size={70} lines={[L("destinada a pessoas", [14.9, 15.58, 15.68]), L("com 18 anos ou mais", [16.12, 16.7, 16.88, 17.32, 17.5], [1, 2, 3, 4])]} />
          <Slot h={440} t={t} at={16.7}>
            <Pop t={t} at={16.7} from={2} rot={-20}>
              <div style={{ width: 440, height: 440, borderRadius: 220, background: LIME, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 30px 80px rgba(0,0,0,0.3)" }}>
                <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 240, color: GREEN, letterSpacing: "-0.04em" }}>18+</span>
              </div>
            </Pop>
          </Slot>
          <Caption t={t} bg="deep" size={56} lines={[L("que ainda não concluíram", [18.04, 18.2, 18.58, 18.8]), L("o Ensino Médio", [19.48, 19.54, 19.9], [1, 2])]} />
        </Stack>
      </Beat>

      {/* 5 · sem aulas regulares */}
      <Beat t={t} a={20.4} b={24.6} bg="cream">
        <Stack gap={56}>
          <Caption t={t} bg="cream" size={62} lines={[L("Nessa modalidade, você", [20.46, 20.74, 21.74]), L("não precisa frequentar", [22.02, 22.2, 22.68], [0, 1]), L("aulas regulares", [23.27, 23.61])]} />
          <Slot h={620} t={t} at={22.6}>
            {(() => {
              const s = sp(t, 22.65, 14, 190);
              const x = k(t, 23.7, 0.35);
              return (
                <div style={{ position: "relative", width: 760, height: 620, borderRadius: 40, background: WHITE, boxShadow: "0 30px 80px rgba(3,40,24,0.2)", overflow: "hidden", opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * 300}px) rotate(${(1 - s) * 5}deg)` }}>
                  <div style={{ height: 130, background: x > 0.5 ? "#9AA8A0" : GREEN, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 52, color: WHITE, letterSpacing: "0.04em" }}>AULAS REGULARES</div>
                  <div style={{ display: "flex", justifyContent: "center", gap: 18, padding: "40px 30px" }}>
                    {["SEG", "TER", "QUA", "QUI", "SEX"].map((d, di) => (
                      <div key={d} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 18 }}>
                        <div style={{ fontFamily: F, fontWeight: 800, fontSize: 30, color: "#9AA8A0" }}>{d}</div>
                        {[0, 1, 2].map((r) => <div key={r} style={{ width: 118, height: 82, borderRadius: 16, background: x > 0.5 ? "#E3E8E4" : ["#2F7BE0", ORANGE, "#7B4BD8"][(r + di) % 3] }} />)}
                      </div>
                    ))}
                  </div>
                  <svg style={{ position: "absolute", left: 0, top: 0 }} width={760} height={620} viewBox="0 0 760 620">
                    <path d="M150 170 L610 570 M610 170 L150 570" stroke={RED} strokeWidth={34} strokeLinecap="round" fill="none" strokeDasharray={1240} strokeDashoffset={1240 * (1 - x)} />
                  </svg>
                </div>
              );
            })()}
          </Slot>
        </Stack>
      </Beat>

      {/* 6 · avaliação de conhecimentos */}
      <Beat t={t} a={24.6} b={29.4} bg="green" wipe>
        <Stack gap={60}>
