import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// DELTA CIDADE JARDIM (Lorrany EJA, mesma escola do cliente "lorran"): vídeo explicativo de como funciona a conclusão
// do Ensino Médio pela EJA. Roteiro da cliente, voz Roberta (ElevenLabs v3), 128,8 s depois de encurtar as pausas longas.
// Identidade dos vídeos anteriores da escola (verde, Montserrat itálica pesada, folha de caderno dos documentos).
// Pedidos da cliente por áudio: card dos documentos como no vídeo anterior, os 5 planos em cards, imagem do certificado;
// ícones podem ter cores próprias.
// Tempos = palavra na voz ((arquivo do cliente)).

const { fontFamily: F } = loadMontserrat("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FI } = loadMontserrat("italic", { weights: ["800", "900"], subsets: ["latin", "latin-ext"] });

export const LY_FPS = 30;
export const LY_DUR = 130.6;
export const LY_FRAMES = Math.round(LY_DUR * LY_FPS);

const GREEN = "#0A6842";
const DEEP = "#053D27";
const NIGHT = "#03271A";
const LEAF = "#5BAA3C";
const LIME = "#B9E27E";
const INK = "#13261C";
const PAPER = "#F4F8F3";
const WHITE = "#FFFFFF";
const GRAY = "#9AA8A0";
const RED = "#E0402F";
const BLUE = "#2F7BE0";
const PURPLE = "#7B4BD8";
const ORANGE = "#F29A1F";
const TEAL = "#2BB3A3";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 14, stiffness = 180) =>
  spring({ frame: Math.round((t - a) * LY_FPS), fps: LY_FPS, config: { damping, stiffness } });
const img = (f: string) => staticFile(`lorrany-eja/${f}`);

// ───────── texto ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number; color?: string; weight?: number; shadow?: boolean }> = ({ t, words, size = 56, color = WHITE, weight = 600, shadow }) => (
  <div style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.18, color, textAlign: "center", whiteSpace: "nowrap", textShadow: shadow ? "0 4px 26px rgba(0,25,15,0.65)" : undefined }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.26);
