  if (t < p.at - 0.02) return <div style={{ width: 840, height: 200 }} />;
  const s = sp(t, p.at, 13, 210);
  const dir = i % 2 ? 1 : -1;
  const shine = lin(t, p.at + 0.35, p.at + 0.95);
  return (
    <div style={{ position: "relative", overflow: "hidden", width: 840, height: 200, flex: "none", boxSizing: "border-box", borderRadius: 34, background: WHITE, border: `5px solid ${GREEN}`, display: "flex", alignItems: "center", padding: "0 34px", gap: 24, boxShadow: "0 22px 50px rgba(0,0,0,0.3)",
      opacity: Math.min(1, s * 3), transform: `translateX(${(1 - s) * 360 * dir}px) rotate(${(1 - s) * 4 * dir}deg)` }}>
      <div style={{ width: 300, flex: "none", padding: "18px 0", borderRadius: 60, background: `linear-gradient(90deg, ${GREEN}, #12B23A)`, textAlign: "center", fontFamily: F, fontWeight: 800, fontSize: 40, color: WHITE, letterSpacing: "0.02em" }}>EJA · {p.name}</div>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 12, whiteSpace: "nowrap" }}>
          {p.x && <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 66, color: GREEN }}>{p.x}</span>}
          <span style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 76, color: RED, letterSpacing: "-0.02em" }}>{p.price}</span>
        </div>
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: 32, color: GREEN, marginTop: -4 }}>{p.note}</div>
      </div>
      {shine > 0 && shine < 1 && <div style={{ position: "absolute", top: -40, bottom: -40, width: 140, left: `${-20 + 140 * shine}%`, background: "linear-gradient(90deg, rgba(185,226,126,0), rgba(185,226,126,0.5), rgba(185,226,126,0))", transform: "skewX(-20deg)" }} />}
    </div>
  );
};

